SourceCode.Declaration:
/// <summary>
/// abstartc record to generat export date for the sales volume report
/// </summary>
abstract public class NDXSNGenData implements NDXExcelDMFExport_Interface
{
    NDXSalesNoteCustomer nDX_SalesNoteCustomer;
    AVATOSId alliance;

    QueryName entityTarget;
    NDXExcelDMFExport lNDXExcelDMFExport;

    Filename fileName = '';
    NDXSignature signature;


}

Method.Source:
/// <summary>
/// abstract method override
/// </summary>
abstract void deleteGeneratedData(){}

protected void new(NDXSalesNoteCustomer _nDX_SalesNoteCustomer)
{
    nDX_SalesNoteCustomer = _nDX_SalesNoteCustomer;
    signature = nDX_SalesNoteCustomer.parmUmsSignature();
}

/// <summary>
/// base populates data method
/// </summary>
protected void pupulateData()
{
    lNDXExcelDMFExport.export(fileName);
    this.deleteGeneratedData();
}

/// <summary>
/// export to excel
/// </summary>
void exportToExcel()
{
    NDXExcelDMFExportSettings ndxExcelDMFExportSettings;

    DMFDefinitionGroup lDMFDefinitionGroup;
    DMFDefinitionGroupEntity lDMFDefinitionGroupEntity;
    DMFEntity lDMFEntity;

    NDXSNAlliance lNDXSNAlliance;

    if(nDX_SalesNoteCustomer != null && nDX_SalesNoteCustomer.nDX_SNAlliance)
    {
        alliance = nDX_SalesNoteCustomer.nDX_SNAlliance.TOSId;
    }

    if(alliance && nDX_SalesNoteCustomer.nDX_SNAlliance.DMFExportProjectRefRecId)
    {
        select firstonly lDMFDefinitionGroup
            join lNDXSNAlliance
                where lNDXSNAlliance.DMFExportProjectRefRecId == lDMFDefinitionGroup.RecId
                && lNDXSNAlliance.TOSId == alliance
            join lDMFDefinitionGroupEntity
                where lDMFDefinitionGroupEntity.DefinitionGroup == lDMFDefinitionGroup.DefinitionGroupName
            join lDMFEntity
                where lDMFEntity.EntityName == lDMFDefinitionGroupEntity.Entity
                && lDMFEntity.TargetEntity == entityTarget;

        if(!lDMFDefinitionGroup)
        {
            Warning("@NDX:NDXSNExportInfo");
            return;
        }

        ndxExcelDMFExportSettings = NDXExcelDMFExportSettings::construct(this.entityTarget, lDMFDefinitionGroup.DefinitionGroupName);
        lNDXExcelDMFExport = NDXExcelDMFExport::construct(ndxExcelDMFExportSettings);

        try
        {
            this.pupulateData();
        }
        catch
        {
            Error("@NDX:NDXSNExportInfo1");
        }

        this.deleteGeneratedData();
    }
}

/// <summary>
/// constructor
/// </summary>
/// <param name = "_nDX_SalesNoteCustomer">NDXSalesNoteCustomer object</param>
/// <returns>NDXSNGenData obejct</returns>
static NDXSNGenData construct(NDXSalesNoteCustomer _nDX_SalesNoteCustomer)
{
    NDXSNGenData lNDXSNGenData = null;
    switch(_nDX_SalesNoteCustomer.nDX_SNAlliance.SalesForAllianceId)
    {
        case 'MITEGRO':
            lNDXSNGenData = NDXSNGenDataMitegro::construct(_nDX_SalesNoteCustomer);
            break;
        case 'FEGIME':
            lNDXSNGenData = NDXSNGenDataFegime::construct(_nDX_SalesNoteCustomer);
            break;
    }

    return  lNDXSNGenData;
}
